import type { ImgHTMLAttributes } from "react";

export type VordiaIsotipoProps = Omit<ImgHTMLAttributes<HTMLImageElement>, "src" | "srcSet">;

// Imagen editada para retirar textos y botones, con base, fondo y reflejo.
// Imagen raster integrada; no es un trazado vectorial ni el archivo maestro.
const IMAGE = "data:image/png;base64,";

export default function VordiaIsotipo({
  alt = "Isotipo VORDIA sobre base iluminada azul",
  style,
  ...props
}: VordiaIsotipoProps) {
  return (
    <img
      width={2170}
      height={725}
      {...props}
      src={IMAGE}
      alt={alt}
      style={{ display: "block", width: "100%", height: "auto", ...style }}
    />
  );
}
